"use client";
import Link from "next/link";
import { usePathname } from "next/navigation";
import { useState } from "react";
import { Button } from "@/components/ui";

const navLinks = [
  { name: "Dashboard", href: "/patient/dashboard" },
  { name: "Appointments", href: "/patient/appointments" },
  { name: "Doctors", href: "/patient/doctors" },
  { name: "Profile", href: "/patient/profile" },
];

export default function Sidebar() {
  const pathname = usePathname();
  const [open, setOpen] = useState(false);

  return (
    <aside className={`bg-white shadow-md h-screen w-64 p-4 flex flex-col fixed z-20 transition-transform duration-200 md:relative md:translate-x-0 ${open ? "translate-x-0" : "-translate-x-full"} md:w-64`}>
      <div className="flex items-center justify-between mb-8 md:hidden">
        <span className="text-lg font-bold text-blue-700">Menu</span>
        <Button variant="ghost" size="icon" onClick={() => setOpen(false)}>
          ✕
        </Button>
      </div>
      <nav className="flex flex-col gap-2">
        {navLinks.map((link) => (
          <Link
            key={link.href}
            href={link.href}
            className={`px-4 py-2 rounded hover:bg-blue-100 transition-colors ${pathname === link.href ? "bg-blue-100 font-semibold text-blue-700" : "text-gray-700"}`}
            onClick={() => setOpen(false)}
          >
            {link.name}
          </Link>
        ))}
      </nav>
      <Button className="md:hidden mt-auto" variant="outline" onClick={() => setOpen(!open)}>
        {open ? "Close" : "Open"} Menu
      </Button>
    </aside>
  );
} 